/* ===================== BÀI 42 · 8253/8254 và định thời ===================== */
/* Bài 42 · 8253/8254 và định thời (AMTS-EMB-002-M11-L02, X86-042) — sinh bởi tools/author/mpu8086/l42.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P42=[{"label": "Ví dụ: sóng vuông 1 kHz ở OUT1", "code": "; Ví dụ 1: sóng vuông 1 kHz ở OUT1 (mode 3)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 76H                 ; bộ đếm 1, LSB rồi MSB, mode 3\n        OUT     8EH, AL                 ; thanh ghi điều khiển 8254\n        MOV     AX, 2500                ; N = 2 500 000 / 1000\n        OUT     8AH, AL                 ; LSB trước\n        MOV     AL, AH\n        OUT     8AH, AL                 ; rồi MSB\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "76h: bộ đếm 1, LSB rồi MSB, mode 3. N = 2500 → 1 kHz: OUT1 mức 1 trong 1250 xung (2500 chu kỳ CPU), mức 0 trong 1250 xung. Xem dạng sóng OUT1 ở phần Bo I/O sau khi chạy (bo chạy thêm sau INT 21h). Đoán trước: sau MOV AX, 2500, AL bằng bao nhiêu (hệ 16)? Đáp án C4h (2500 = 09C4h)."}, {"label": "Ví dụ: xung nhịp 10 kHz ở OUT0 (mode 2)", "code": "; Ví dụ 2: xung nhịp 10 kHz ở OUT0 (mode 2)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 34H                 ; bộ đếm 0, LSB rồi MSB, mode 2\n        OUT     8EH, AL                 ; thanh ghi điều khiển 8254\n        MOV     AX, 250                 ; N = 2 500 000 / 10 000\n        OUT     88H, AL                 ; LSB trước\n        MOV     AL, AH\n        OUT     88H, AL                 ; rồi MSB\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "34h: bộ đếm 0, mode 2. N = 250 → 10 kHz; OUT0 xuống 0 đúng một xung CLK (0,4 µs) mỗi 100 µs, đó là xung sẽ gây ngắt định thời ở Bài 43. Đoán trước: chu kỳ OUT0 dài bao nhiêu chu kỳ CPU? Đáp án 500."}, {"label": "Bẫy: mode 3 với N lẻ (N = 25)", "code": "; Bẫy: mode 3 với N lẻ không cho đúng 50%\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 76H                 ; bộ đếm 1, LSB rồi MSB, mode 3\n        OUT     8EH, AL                 ; thanh ghi điều khiển 8254\n        MOV     AX, 25                  ; N lẻ\n        OUT     8AH, AL                 ; LSB trước\n        MOV     AL, AH\n        OUT     8AH, AL                 ; rồi MSB\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: mode 3 với N = 25 (lẻ): mức 1 trong 13 xung (26 chu kỳ CPU), mức 0 trong 12 xung: duty 52 %, không phải 50 %. Đoán trước: OUT1 ở mức 1 bao nhiêu xung CLK? Đáp án 13."}, {"label": "Lỗi: chỉ ghi LSB khi RW = 11", "code": "; Lỗi: RW = 11 nhưng chỉ ghi LSB\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 76H                 ; bộ đếm 1, LSB rồi MSB, mode 3\n        OUT     8EH, AL\n        MOV     AX, 2500\n        OUT     8AH, AL                 ; LSB; thiếu MSB: bộ đếm chờ mãi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: RW = 11 nhưng chỉ ghi LSB. 8254 chờ byte MSB nên chưa nạp N, OUT1 đứng ở mức 1, không có dạng sóng. Sửa: MOV AL, AH / OUT 8Ah, AL (Ví dụ 1), hoặc dùng RW = 01 nếu N ≤ 255."}, {"label": "Ví dụ: đo thời gian bằng lệnh chốt", "code": "; Ví dụ 5: đo thời gian một đoạn code bằng lệnh chốt\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DW      ?                       ; giá trị chốt được\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 30H                 ; bộ đếm 0, LSB rồi MSB, mode 0\n        OUT     8EH, AL\n        MOV     AL, 0FFH\n        OUT     88H, AL                 ; LSB = FFh\n        OUT     88H, AL                 ; MSB = FFh: N = 65535\n        MOV     CX, 10\ncho:\n        LOOP    cho                     ; đoạn cần đo\n        MOV     AL, 00H                 ; lệnh chốt bộ đếm 0 (RW = 00)\n        OUT     8EH, AL\n        IN      AL, 88H                 ; LSB đã chốt\n        MOV     AH, AL\n        IN      AL, 88H                 ; MSB đã chốt\n        XCHG    AL, AH                  ; AX = giá trị chốt\n        MOV     dem, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Mode 0, N = FFFFh. Bộ đếm nạp ở xung CLK đầu tiên sau lệnh ghi MSB, rồi giảm 1 mỗi 2 chu kỳ CPU trong lúc LOOP chạy 10 vòng (9 × 17 + 5 = 158 chu kỳ). Lệnh chốt (00h ra 8Eh) giữ giá trị FFA8h; hai lệnh IN đọc A8h rồi FFh. FFFFh − FFA8h = 87 xung = 34,8 µs. Đoán trước: sau lệnh IN đầu tiên, AL bằng bao nhiêu? Đáp án A8h."}, {"label": "Lỗi: tính N theo xung nhịp CPU", "code": "; Lỗi: tính N theo xung nhịp CPU 5 MHz\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 76H                 ; bộ đếm 1, LSB rồi MSB, mode 3\n        OUT     8EH, AL                 ; thanh ghi điều khiển 8254\n        MOV     AX, 5000                ; SAI: 5 000 000 / 1000\n        OUT     8AH, AL                 ; LSB trước\n        MOV     AL, AH\n        OUT     8AH, AL                 ; rồi MSB\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: N tính theo 5 MHz của CPU (5000) thay cho CLK 2,5 MHz của 8254 → OUT1 chỉ 500 Hz, chu kỳ 10 000 chu kỳ CPU (2 ms). Sửa: N = 2 500 000 / 1000 = 2500."}, {"label": "Ví dụ: xung đơn 400 µs, kích bằng GATE1", "code": "; Ví dụ 7: xung đơn 400 us ở OUT1, kích bằng GATE1 = PC0\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 72H                 ; bộ đếm 1, LSB rồi MSB, mode 1\n        OUT     8EH, AL                 ; thanh ghi điều khiển 8254\n        MOV     AX, 1000\n        OUT     8AH, AL                 ; LSB trước\n        MOV     AL, AH\n        OUT     8AH, AL                 ; rồi MSB\n        MOV     AL, 8AH                 ; 8255A: C cao vào, C thấp ra, PC0 = 0\n        OUT     86H, AL\n        MOV     AL, 01H                 ; BSR lập PC0: cạnh lên ở GATE1\n        OUT     86H, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "72h: bộ đếm 1 mode 1 (xung đơn). Bộ đếm chờ cạnh lên của GATE1 = PC0: từ điều khiển 8Ah (C cao vào vì nối nút, C thấp ra) đặt PC0 = 0, rồi BSR 01h lập PC0 → cạnh lên → OUT1 xuống 0 trong 1000 xung = 400 µs (2000 chu kỳ CPU) rồi lên lại. Đoán trước: trước lệnh BSR, OUT1 ở mức nào? Đáp án 1."}];
