const EX42=[{"t": "Sóng vuông N = công tắc × 100", "d": "Bo I/O: 8254 ở 88h–8Eh, CLK = 2,5 MHz; 8255A ở 80h–86h, PB nối 8 công tắc, GATE1 của 8254 nối PC0 (cổng C thấp để là cổng vào thì GATE1 = 1 nhờ điện trở kéo lên, giả định). Đặt 8255A bằng từ điều khiển 8Bh (B vào, C cao và C thấp vào). Đọc công tắc (giá trị s từ 1 tới 255), tính N = s × 100, ghi N vào biến soDem (word) rồi cho bộ đếm 1 tạo sóng vuông (mode 3, nhị phân) với số đếm N. Kết thúc bằng INT 21h hàm 4Ch. Trang chấm mode, số nạp và chu kỳ xung đo được ở OUT1 (2N chu kỳ CPU).", "start": "; Bài tập 1: sóng vuông N = công tắc x 100 ở OUT1\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsoDem   DW      ?                       ; N đã nạp\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 8BH                 ; 8255A: B, C cao, C thấp vào (GATE1=1)\n        OUT     86H, AL\n        IN      AL, 82H                 ; AL = công tắc (1-255)\n; TODO: N = AL x 100, ghi vào soDem; bộ đếm 1 mode 3\n;       (từ điều khiển 76h), nạp LSB rồi MSB\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"io": {"sw": 25, "run": 120000, "want": {"pit": {"1": {"mode": 3, "count": 2500, "period": 5000}}}}, "mem": [{"at": "soDem", "word": 2500}]}, {"io": {"sw": 1, "run": 120000, "want": {"pit": {"1": {"mode": 3, "count": 100, "period": 200}}}}, "mem": [{"at": "soDem", "word": 100}]}, {"io": {"sw": 255, "run": 120000, "want": {"pit": {"1": {"mode": 3, "count": 25500, "period": 51000}}}}, "mem": [{"at": "soDem", "word": 25500}]}, {"io": {"sw": 10, "run": 120000, "want": {"pit": {"1": {"mode": 3, "count": 1000, "period": 2000}}}}, "mem": [{"at": "soDem", "word": 1000}]}, {"io": {"sw": 50, "run": 120000, "want": {"pit": {"1": {"mode": 3, "count": 5000, "period": 10000}}}}, "mem": [{"at": "soDem", "word": 5000}]}, {"io": {"sw": 128, "run": 120000, "want": {"pit": {"1": {"mode": 3, "count": 12800, "period": 25600}}}}, "mem": [{"at": "soDem", "word": 12800}]}]}, {"t": "Tần số từ bàn phím", "d": "Code mẫu đã đọc một số thập phân f (Hz, từ 39 tới 65535) vào BX. Tính N = (2 500 000 + f/2) / f (chia lấy phần nguyên: làm tròn tới số gần nhất), ghi N vào biến soDem rồi cho bộ đếm 0 chạy mode 2 với số đếm N (LSB rồi MSB). Kết thúc bằng INT 21h hàm 4Ch. Không in gì.", "start": "; Bài tập 2: tần số từ bàn phím → N cho OUT0 (mode 2)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsoDem   DW      ?                       ; N đã nạp\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; --- đọc số thập phân (tới Enter) vào BX ---\n        XOR     BX, BX\ndoc:\n        MOV     AH, 01H\n        INT     21H\n        CMP     AL, 0DH                 ; Enter?\n        JE      xong\n        SUB     AL, '0'\n        MOV     CL, AL\n        MOV     CH, 0\n        MOV     AX, 10\n        MUL     BX                      ; AX = BX x 10\n        ADD     AX, CX\n        MOV     BX, AX\n        JMP     doc\nxong:                                   ; BX = f (Hz)\n; TODO: N = (2 500 000 + f/2) / f, ghi soDem,\n;       bộ đếm 0 mode 2 (34h), LSB rồi MSB\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "1000", "io": {"run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 2500}}}}, "mem": [{"at": "soDem", "word": 2500}]}, {"in": "440", "io": {"run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 5682}}}}, "mem": [{"at": "soDem", "word": 5682}]}, {"in": "50", "io": {"run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 50000}}}}, "mem": [{"at": "soDem", "word": 50000}]}, {"in": "39", "io": {"run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 64103}}}}, "mem": [{"at": "soDem", "word": 64103}]}, {"in": "60000", "io": {"run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 42}}}}, "mem": [{"at": "soDem", "word": 42}]}, {"in": "3000", "io": {"run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 833}}}}, "mem": [{"at": "soDem", "word": 833}]}]}, {"t": "Ba bộ đếm, ít byte và ít chu kỳ", "d": "Cho cùng lúc: bộ đếm 0 mode 2 với N = 100; bộ đếm 1 mode 3 với N = s × 256 (s là giá trị 8 công tắc, 1–255); bộ đếm 2 mode 3 với N = 16. Giữ từ điều khiển 8Bh cho 8255A (GATE1 = 1). Code mẫu đúng nhưng mọi bộ đếm đều nạp 2 byte. Viết lại để đạt cả giới hạn chu kỳ và byte mã, bằng cách chọn trường RW (chỉ LSB, chỉ MSB) hợp với từng số đếm. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: ba bộ đếm, ít byte và ít chu kỳ\n; Bản này đúng nhưng mọi bộ đếm đều ghi 2 byte.\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 8BH                 ; 8255A: B, C cao, C thấp vào (GATE1=1)\n        OUT     86H, AL\n        IN      AL, 82H\n        MOV     BL, AL                  ; BL = công tắc\n        MOV     AL, 34H                 ; bộ đếm 0: N = 100, mode 2\n        OUT     8EH, AL\n        MOV     AX, 100\n        OUT     88H, AL\n        MOV     AL, AH\n        OUT     88H, AL\n        MOV     AL, 76H                 ; bộ đếm 1: N = BL x 256, mode 3\n        OUT     8EH, AL\n        MOV     AH, BL\n        MOV     AL, 0\n        OUT     8AH, AL\n        MOV     AL, AH\n        OUT     8AH, AL\n        MOV     AL, 0B6H                ; bộ đếm 2: N = 16, mode 3\n        OUT     8EH, AL\n        MOV     AX, 16\n        OUT     8CH, AL\n        MOV     AL, AH\n        OUT     8CH, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"io": {"sw": 1, "run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 100}, "1": {"mode": 3, "count": 256}, "2": {"mode": 3, "count": 16}}}}}, {"io": {"sw": 2, "run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 100}, "1": {"mode": 3, "count": 512}, "2": {"mode": 3, "count": 16}}}}}, {"io": {"sw": 10, "run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 100}, "1": {"mode": 3, "count": 2560}, "2": {"mode": 3, "count": 16}}}}}, {"io": {"sw": 100, "run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 100}, "1": {"mode": 3, "count": 25600}, "2": {"mode": 3, "count": 16}}}}}, {"io": {"sw": 255, "run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 100}, "1": {"mode": 3, "count": 65280}, "2": {"mode": 3, "count": 16}}}}}, {"io": {"sw": 128, "run": 1000, "want": {"pit": {"0": {"mode": 2, "count": 100}, "1": {"mode": 3, "count": 32768}, "2": {"mode": 3, "count": 16}}}}}], "perf": {"cycles": 175, "bytes": 40}}];
