makeQuiz("quiz42","score42",[{"q": "Cần bộ đếm 2 của 8254 tạo sóng vuông, nạp số đếm LSB rồi MSB, đếm nhị phân. Từ điều khiển là bao nhiêu?", "o": ["B6h", "76h", "36h", "B4h"], "a": 0, "e": "SC = 10 (bộ đếm 2), RW = 11, M = 011 (mode 3), BCD = 0 → 1011 0110b = B6h. 76h là bộ đếm 1; 36h là bộ đếm 0; B4h là mode 2."}, {"q": "CLK của 8254 là 2,5 MHz. Cần sóng 50 Hz ở mode 3. Số đếm N là bao nhiêu và có nạp được không?", "o": ["N = 100 000, phải chia đôi vì quá 16 bit", "N = 5000, vì N = f_CLK / (10 × f)", "N = 25 000, vì mode 3 đếm hai lần mỗi chu kỳ", "N = 50 000, vừa 16 bit nên nạp được"], "a": 3, "e": "N = 2 500 000 / 50 = 50 000 ≤ 65 535 nên nạp được (C350h). Tần số thấp nhất một bộ đếm tạo được là 2 500 000 / 65 536 ≈ 38,1 Hz."}, {"q": "Mode 3 với N = 5. Trong mỗi chu kỳ OUT, mức 1 và mức 0 kéo dài bao nhiêu xung CLK?", "o": ["Mức 1: 2,5 xung, mức 0: 2,5 xung", "Mức 1: 3 xung, mức 0: 2 xung", "Mức 1: 4 xung, mức 0: 1 xung", "Mức 1: 2 xung, mức 0: 3 xung"], "a": 1, "e": "Mode 3 với N lẻ: mức 1 trong (N + 1)/2 = 3 xung, mức 0 trong (N − 1)/2 = 2 xung (Hình 42.2). Mức 0 một xung là đặc điểm của mode 2."}, {"q": "Muốn đọc giá trị bộ đếm 0 đang chạy mà không bị lẫn LSB và MSB, cần làm gì?", "o": ["Đọc 88h hai lần thật nhanh liên tiếp", "Ghi lại từ điều khiển 34h rồi đọc 88h", "Đặt GATE0 = 0 rồi đọc 88h hai lần", "Ghi 00h vào 8Eh (lệnh chốt) rồi đọc 88h hai lần"], "a": 3, "e": "Lệnh chốt (RW = 00) chép giá trị hiện tại vào thanh ghi chốt; hai lần đọc sau trả LSB rồi MSB của giá trị đó trong khi bộ đếm vẫn chạy. Ghi lại từ điều khiển làm bộ đếm khởi động lại; GATE0 trên bo cố định bằng 1."}, {"q": "Đoạn code ghi <code>76h<\/code> vào 8Eh rồi ghi đúng một byte <code>C4h<\/code> vào 8Ah. OUT1 thế nào?", "o": ["Sóng vuông với N = C4h = 196", "Sóng vuông với N = 2500 vì MSB tự lấy byte cũ", "Đứng ở mức 1: bộ đếm còn chờ byte MSB nên chưa nạp N", "Mức 0 cố định vì N chưa hợp lệ"], "a": 2, "e": "76h có RW = 11 (LSB rồi MSB): 8254 chỉ nạp N khi nhận đủ hai byte (Ví dụ 4). Sau khi ghi từ điều khiển mode 3, OUT ở mức 1."}]);

